import * as React from 'react'

import { cx } from '~/lib/cx'
import styles from './timeline.module.scss'

export type TimelineStatus = 'default' | 'active' | 'done' | 'muted'
/** Colour of the default dot. Add your own if you fork the file. */
export type TimelineTone = 'neutral' | 'active' | 'success' | 'danger' | 'muted'
export type TimelineOrientation = 'vertical' | 'horizontal'

type ConnectorContext = {
  status: string
  orientation: TimelineOrientation
}

const LEGACY_TONE: Record<TimelineStatus, TimelineTone> = {
  default: 'neutral',
  active: 'active',
  done: 'success',
  muted: 'muted',
}

const TONE: Record<TimelineTone, string> = {
  neutral: styles.toneNeutral,
  active: styles.toneActive,
  success: styles.toneSuccess,
  danger: styles.toneDanger,
  muted: styles.toneMuted,
}

type TimelineContextValue = {
  orientation: TimelineOrientation
  align: 'start' | 'end'
  connector?: (context: ConnectorContext) => React.ReactNode
  pulse: boolean
  rail: boolean
}

const TimelineContext = React.createContext<TimelineContextValue>({
  orientation: 'vertical',
  align: 'start',
  pulse: false,
  rail: true,
})

export type TimelineProps = React.ComponentProps<'ol'> & {
  /** Vertical list (default) or one column per step on a horizontal rail. */
  orientation?: TimelineOrientation
  /** Vertical only: put the rail on the end side. */
  align?: 'start' | 'end'
  /** Replace the connector segment drawn between nodes. */
  connector?: (context: ConnectorContext) => React.ReactNode
  /** Sweep a light pulse along the default connector. */
  pulse?: boolean
  /**
   * Render the rail column with its nodes and connectors (default). Pass
   * `false` to place nodes yourself — e.g. on the corners of a custom path.
   */
  rail?: boolean
  /**
   * Layer painted behind the items. Return an `<svg>` here to draw a custom
   * path (rope, snake, curve) instead of straight connectors — pair it with
   * `connector={() => null}`. The layer already covers the timeline box.
   */
  path?: React.ReactNode
}

function Timeline({
  className,
  orientation = 'vertical',
  align = 'start',
  connector,
  pulse = false,
  rail = true,
  path,
  children,
  ...props
}: TimelineProps) {
  const context = React.useMemo(
    () => ({ orientation, align, connector, pulse, rail }),
    [orientation, align, connector, pulse, rail],
  )

  return (
    <TimelineContext.Provider value={context}>
      <ol
        data-orientation={orientation}
        data-align={align}
        className={cx(
          styles.root,
          orientation === 'vertical'
            ? styles.rootVertical
            : styles.rootHorizontal,
          className,
        )}
        {...props}
      >
        {path ? (
          <li aria-hidden className={styles.path}>
            {path}
          </li>
        ) : null}
        {children}
      </ol>
    </TimelineContext.Provider>
  )
}

export type TimelineItemProps = React.ComponentProps<'li'> & {
  /**
   * Any string — `default`/`active`/`done`/`muted` are built in, anything
   * else (e.g. `shipped`) is exposed as `data-status` for your own styles.
   */
  status?: TimelineStatus | (string & {})
  /** Dot colour. Defaults from the legacy status names, else `neutral`. */
  tone?: TimelineTone
  /**
   * Compact marker rendered in the rail instead of a dot — a date, a step
   * number, anything. The rail widens to fit.
   */
  date?: React.ReactNode
  /** Machine-readable value for the `date` marker (`<time dateTime>`). */
  dateTime?: string
  /**
   * Replaces the marker entirely — an icon, avatar image, initials, or any
   * custom status component.
   */
  indicator?: React.ReactNode
  /** Extra classes for the node wrapper (position it when `rail={false}`). */
  indicatorClassName?: string
}

function TimelineItem({
  className,
  status = 'default',
  tone,
  date,
  dateTime,
  indicator,
  indicatorClassName,
  children,
  ...props
}: TimelineItemProps) {
  const { orientation, align, connector, pulse, rail } =
    React.useContext(TimelineContext)
  const resolvedTone =
    tone ?? LEGACY_TONE[status as TimelineStatus] ?? 'neutral'
  const toneClass = TONE[resolvedTone]
  const marker =
    indicator ??
    (date !== undefined ? (
      <time dateTime={dateTime} className={styles.marker}>
        {date}
      </time>
    ) : undefined)
  const custom = marker !== undefined

  const node = (
    <span
      data-status={status}
      className={cx(
        styles.node,
        !custom && styles.dot,
        toneClass,
        resolvedTone === 'muted' && styles.muted,
        indicatorClassName,
      )}
    >
      {marker}
    </span>
  )

  const segment = (extra: string) => (
    <span aria-hidden className={cx(styles.segment, extra)}>
      {connector ? (
        connector({ status, orientation })
      ) : (
        <span
          className={cx(
            styles.line,
            orientation === 'vertical'
              ? styles.lineVertical
              : styles.lineHorizontal,
            pulse &&
              (orientation === 'horizontal'
                ? styles.pulseHorizontal
                : styles.pulseVertical),
          )}
        />
      )}
    </span>
  )

  if (orientation === 'horizontal') {
    return (
      <li
        data-status={status}
        className={cx(styles.item, styles.itemHorizontal, className)}
        {...props}
      >
        <div className={styles.horizontalHead}>
          {node}
          {segment(styles.segmentHorizontal)}
        </div>
        <div className={styles.horizontalContent}>{children}</div>
      </li>
    )
  }

  if (!rail) {
    return (
      <li
        data-status={status}
        className={cx(styles.item, styles.itemNoRail, className)}
        {...props}
      >
        {custom ? (
          <span
            data-status={status}
            className={cx(
              styles.freeNode,
              toneClass,
              resolvedTone === 'muted' && styles.muted,
              indicatorClassName,
            )}
          >
            {marker}
          </span>
        ) : null}
        {children}
      </li>
    )
  }

  return (
    <li
      data-status={status}
      className={cx(
        styles.item,
        styles.itemRail,
        align === 'end' ? styles.railEnd : styles.railStart,
        className,
      )}
      {...props}
    >
      <div
        className={cx(
          styles.railColumn,
          align === 'end' && styles.railColumnEnd,
        )}
      >
        {segment(styles.segmentVertical)}
        {/* Height matches the first line box, so any node size centres on it. */}
        <span className={styles.nodeRow}>{node}</span>
      </div>
      <div className={styles.railContent}>{children}</div>
    </li>
  )
}

function TimelineTitle({ className, ...props }: React.ComponentProps<'h3'>) {
  return <h3 className={cx(styles.title, className)} {...props} />
}

function TimelineDescription({
  className,
  ...props
}: React.ComponentProps<'p'>) {
  return <p className={cx(styles.description, className)} {...props} />
}

function TimelineTime({ className, ...props }: React.ComponentProps<'time'>) {
  return <time className={cx(styles.time, className)} {...props} />
}

export {
  Timeline,
  TimelineItem,
  TimelineTitle,
  TimelineDescription,
  TimelineTime,
}

@use 'styles' as vz;

.root {
  position: relative;
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
}

.root-vertical {
  flex-direction: column;
}

.root-horizontal {
  flex-direction: row;
  align-items: flex-start;
  width: 100%;
  min-width: 0;
  padding-bottom: vz.space(1);
  overflow-x: auto;

  @include vz.scrollbar;
}

.path {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.item {
  position: relative;
}

.item-rail {
  display: grid;
  column-gap: vz.space(3);
}

.rail-start {
  grid-template-columns: minmax(1.25rem, auto) minmax(0, 1fr);
}

.rail-end {
  grid-template-columns: minmax(0, 1fr) minmax(1.25rem, auto);
}

.rail-column {
  position: relative;
  display: flex;
  justify-content: center;
}

.rail-column-end {
  order: 2;
}

.node-row {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 1.25rem;
}

.rail-content {
  min-width: 0;
  padding-bottom: vz.space(8);
}

.item:last-child .rail-content {
  padding-bottom: 0;
}

.node {
  position: relative;
  z-index: 1;
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
}

.dot {
  width: 0.75rem;
  height: 0.75rem;
  border: 2px solid var(--node-border);
  border-radius: vz.radius('full');
  background: var(--node-bg);
}

.marker {
  display: block;
  color: var(--marker-color);
  font-size: 0.625rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  line-height: 1.2;
  text-align: center;
  text-transform: uppercase;
}

.tone-neutral {
  --node-bg: #{vz.color('background')};
  --node-border: #{vz.color('border')};
  --marker-color: #{vz.color('muted-foreground')};
}

.tone-active {
  --node-bg: #{vz.color('ring')};
  --node-border: #{vz.color('ring')};
  --marker-color: #{vz.color('ring')};
}

.tone-success {
  --node-bg: #{vz.color('success')};
  --node-border: #{vz.color('success')};
  --marker-color: #{vz.color('success')};
}

.tone-danger {
  --node-bg: #{vz.color('destructive')};
  --node-border: #{vz.color('destructive')};
  --marker-color: #{vz.color('destructive')};
}

.tone-muted {
  --node-bg: #{vz.color('background')};
  --node-border: #{vz.color('border')};
  --marker-color: #{vz.color('muted-foreground')};
}

.muted {
  opacity: 0.5;
}

.segment {
  display: block;
}

.segment-vertical {
  position: absolute;
  top: vz.space(3);
  bottom: 0;
  display: flex;
  width: 100%;
  justify-content: center;
}

.segment-horizontal {
  position: relative;
  display: flex;
  flex: 1;
  align-items: center;
  height: 1px;
  margin-inline-start: vz.space(1.5);
}

.line {
  display: block;
  background: vz.color('border');
}

.line-vertical {
  width: 1px;
  height: 100%;
}

.line-horizontal {
  width: 100%;
  height: 1px;
}

.item:last-child .segment-vertical,
.item:last-child .segment-horizontal {
  display: none;
}

.item-no-rail {
  min-width: 0;
  padding-bottom: vz.space(8);
}

.item-no-rail:last-child {
  padding-bottom: 0;
}

.free-node {
  position: absolute;
  top: 0;
  inset-inline-start: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.item-horizontal {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 9rem;
}

.horizontal-head {
  display: flex;
  align-items: center;
}

.horizontal-content {
  min-width: 0;
  padding-top: vz.space(2);
  padding-inline-end: vz.space(4);
}

.item-horizontal:last-child .horizontal-content {
  padding-inline-end: 0;
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.description {
  margin: vz.space(1) 0 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.5;
}

.time {
  display: block;
  margin-bottom: vz.space(1);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}

.pulse-vertical {
  background-image: linear-gradient(
    to bottom,
    transparent,
    #{vz.color('ring', 0.9)},
    transparent
  );
  background-repeat: no-repeat;
  background-size: 100% 40%;
  animation: vz-timeline-pulse-y 1.8s linear infinite;
}

.pulse-horizontal {
  background-image: linear-gradient(
    to right,
    transparent,
    #{vz.color('ring', 0.9)},
    transparent
  );
  background-repeat: no-repeat;
  background-size: 40% 100%;
  animation: vz-timeline-pulse-x 1.8s linear infinite;
}

@include vz.motion-reduce {
  .pulse-vertical,
  .pulse-horizontal {
    background-image: none;
    animation: none;
  }
}

@keyframes vz-timeline-pulse-y {
  0% {
    background-position: 50% -60%;
  }

  100% {
    background-position: 50% 160%;
  }
}

@keyframes vz-timeline-pulse-x {
  0% {
    background-position: -60%;
  }

  100% {
    background-position: 160%;
  }
}
